 return <section className="letterWorkspace"><div className="letterTopbar"><div><span className="eyebrow">ONLINE DOCUMENT BUILDER</span><h2>จัดทำหนังสือออนไลน์</h2><p>แก้ข้อความและตรวจตารางก่อนพิมพ์เป็น PDF</p></div><div className="letterKindSwitch"><button type="button" className={kind==="approval"?"active":"ghost"} onClick={()=>setKind("approval")}>หนังสืออนุมัติ</button><button type="button" className={kind==="mt"?"active":"ghost"} onClick={()=>setKind("mt")}>หนังสือ มท.</button></div><div className="letterPrintActions"><button type="button" className="ghost" onClick={convertLetterPaperDigits}>แปลงเป็นเลขไทย</button><button type="button" onClick={()=>{convertLetterPaperDigits();window.print()}}>พิมพ์ / PDF</button></div></div><div className="letterLayout"><aside className="letterEditor"><div className="letterEditorHead"><b>ข้อมูลแทนที่ข้อความ</b><span>บันทึกอัตโนมัติในเครื่องนี้</span></div>{letterFieldLabels[kind].map(field=><label key={field.key}><span><b>{field.label}</b><small>{field.key}</small></span>{field.large?<textarea rows={5} value={fields[field.key]||""} onChange={event=>update(field.key,event.target.value)}/>:<input value={fields[field.key]||""} onChange={event=>update(field.key,event.target.value)}/>}</label>)}{kind==="mt"&&<label className="letterOption"><span><b>แบบลงนามงานก่อสร้าง</b><small>หน้าที่ 3</small></span><input type="checkbox" checked={includeConstructionForm} onChange={event=>setIncludeConstructionForm(event.target.checked)}/></label>}<div className="letterTableStatus"><b>ตารางค่าใช้จ่าย</b><span>{result?"เชื่อมจากผลคำนวณล่าสุดแล้ว":"กรุณาสร้างสรุปค่าใช้จ่ายก่อน"}</span></div></aside><LetterPaper kind={kind} project={project} fields={fields} result={result} sections={sections} hiddenSections={hiddenSubtopicSections} mainSectionNo={subtopicMainNumber} includeConstructionForm={includeConstructionForm}/></div></section>
